#!/usr/bin/env node
/**
 * Sync live SFCC site/locale/currency config into the *.generated.* files
 * that back config/sites.js, overrides/app/config/countries.ts,
 * overrides/app/config/contentfulMapping.ts, and e2e/fixtures/site.js.
 *
 * Reads config/sites.overlay.js (hand-maintained routing data: alias,
 * sfccSiteId) to find the real SFCC site IDs to query, fetches each site's
 * live configuration via the Shopper Configurations API (SCAPI — the
 * current, non-deprecated successor to OCAPI's Data API site-preferences
 * read), then derives four outputs from that single fetch:
 *
 *   config/sites.generated.js                     — per real SFCC site
 *   overrides/app/config/countries.generated.ts    — per URL slug
 *   overrides/app/config/contentfulMapping.generated.ts — per PWA site id
 *   e2e/fixtures/site.generated.js                 — per e2e fixture key
 *
 * Each consuming file (config/sites.js, countries.ts, contentfulMapping.ts,
 * e2e/fixtures/site.js) merges its .generated file with a small
 * hand-maintained overlay carrying the fields Business Manager/SCAPI has no
 * concept of (URL aliases, checkout ownership, shipping country, boutique
 * region, fixture-key naming) — see each file for its own merge logic.
 *
 * Write access to all four generated files is gated to
 * @ZimmermannAU/tier-1-approvers, same pattern as
 * scripts/contentful/setup/getConfig.mjs. Non-approvers get a read-only
 * dry-run. (Only config/sites.generated.js sits under a directory
 * frozenFiles.md explicitly marks Tier 1 — the other three are gated the
 * same way anyway, since they carry the same class of routing-critical
 * data.)
 *
 * Usage:
 *   npm run sync:regional-config
 *   npm run sync:regional-config -- --dry-run
 */

import { execSync } from 'child_process';
import { existsSync, renameSync, unlinkSync, writeFileSync } from 'fs';
import { createRequire } from 'module';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';
import { checkEnv, fetchSiteConfiguration, getSlasToken, isTier1Approver, log } from './_shared.mjs';

const require = createRequire(import.meta.url);
const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '../../');
const DRY_RUN = process.argv.includes('--dry-run');

const SITES_OVERLAY_FILE = resolve(REPO_ROOT, 'config/sites.overlay.js');
const E2E_OVERLAY_FILE = resolve(REPO_ROOT, 'e2e/fixtures/site.overlay.js');

// AU is the app's defaultSite (config/default.js) and, by PWA Kit
// convention, the one site with no URL alias — every other site's slug
// comes directly from its locale's `alias` in sites.overlay.js.
const ROOT_SITE_ID = 'ZimmermannAU';
const ROOT_SLUG = 'au';

const TARGETS = {
  sites: {
    file: resolve(REPO_ROOT, 'config/sites.generated.js'),
    format: 'cjs',
    consumer: 'config/sites.js',
  },
  countries: {
    file: resolve(REPO_ROOT, 'overrides/app/config/countries.generated.ts'),
    format: 'ts',
    exportName: 'GENERATED_COUNTRIES',
    consumer: 'overrides/app/config/countries.ts',
  },
  contentful: {
    file: resolve(REPO_ROOT, 'overrides/app/config/contentfulMapping.generated.ts'),
    format: 'ts-contentful',
    consumer: 'overrides/app/config/contentfulMapping.ts',
  },
  e2eSite: {
    file: resolve(REPO_ROOT, 'e2e/fixtures/site.generated.js'),
    format: 'cjs',
    consumer: 'e2e/fixtures/site.js',
  },
};

checkEnv([
  'COMMERCE_API_SHORT_CODE',
  'COMMERCE_API_ORGANIZATION_ID',
  'COMMERCE_API_CLIENT_ID',
  'PWA_KIT_SLAS_CLIENT_SECRET',
]);

/**
 * Extracts the fields these targets need from a Shopper Configurations
 * response. The real response shape (confirmed against a live dev-realm
 * call, not documented in the SDK's `any`-typed value field) is a FLAT
 * array of `{configurationType, id, value}` entries — one per field, not a
 * single nested object — mixing `siteConfiguration` entries (id/name/status/
 * timezone/defaultCurrency/allowedCurrencies/defaultLocale/allowedLocales)
 * with unrelated `globalConfiguration` entries (SalesforcePaymentsAllowed,
 * my_domain). `allowedLocales` entries are rich objects
 * ({id, country, displayName, ...}) with NO per-locale currency field, and
 * always include a placeholder `{id: 'default', ...}` entry that isn't a
 * real locale. Since every site here uses a single currency across all its
 * locales (confirmed against the existing config/sites.js data), each real
 * locale is assigned the site's own `defaultCurrency` as its
 * `preferredCurrency` rather than reading a (non-existent) per-locale value.
 */
function extractSiteConfig(siteId, rawResponse) {
  const fields = Object.fromEntries(
    (rawResponse?.configurations ?? [])
      .filter((c) => c.configurationType === 'siteConfiguration')
      .map((c) => [c.id, c.value]),
  );

  // Fatal, not a warning: a malformed response for one site must abort the
  // whole sync rather than silently drop that region from all four
  // generated files while the run reports success for the rest.
  const missingFields = ['defaultLocale', 'defaultCurrency', 'allowedCurrencies', 'allowedLocales'].filter(
    (f) => !fields[f] || (Array.isArray(fields[f]) === false && (f === 'allowedCurrencies' || f === 'allowedLocales')),
  );
  if (missingFields.length) {
    log.error(
      `Incomplete Shopper Configurations response for '${siteId}' (missing ${missingFields.join(
        ', ',
      )}) — raw response below.`,
    );
    console.log(JSON.stringify(rawResponse, null, 2));
    throw new Error(`Incomplete Shopper Configurations response for '${siteId}'.`);
  }

  const defaultCurrency = fields.defaultCurrency;
  return {
    status: fields.status,
    defaultLocale: fields.defaultLocale,
    defaultCurrency,
    supportedCurrencies: fields.allowedCurrencies,
    supportedLocales: fields.allowedLocales
      .filter((l) => l.id !== 'default')
      .map((l) => ({ id: l.id, preferredCurrency: defaultCurrency })),
  };
}

/** ISO 4217 code -> display symbol (e.g. 'AUD' -> 'A$'), matching the
 * disambiguated form Zimmermann's e2e fixtures already used by hand. */
function currencySymbolFor(currencyCode) {
  return new Intl.NumberFormat('en', { style: 'currency', currency: currencyCode })
    .formatToParts(1)
    .find((p) => p.type === 'currency').value;
}

/**
 * Derives config/sites.generated.js's shape: real SFCC site id -> live
 * config. Deliberately does NOT catch per-site failures — a transient SCAPI
 * error or a malformed response for one site must abort the entire sync
 * (nothing gets written, see main()) rather than silently ship a config
 * that's missing that region across all four generated files.
 */
async function fetchGeneratedSites(overlay) {
  const realSiteIds = [...new Set(overlay.map((s) => s.sfccSiteId ?? s.id))];
  log.info(`Real SFCC sites to sync (deduped from ${overlay.length} PWA sites): ${realSiteIds.join(', ')}`);

  const generated = {};
  for (const siteId of realSiteIds) {
    const accessToken = await getSlasToken(siteId);
    const raw = await fetchSiteConfiguration(accessToken, siteId);
    generated[siteId] = extractSiteConfig(siteId, raw);
    const localeList = generated[siteId].supportedLocales.map((l) => l.id).join(',');
    const currencyList = generated[siteId].supportedCurrencies?.join(',');
    log.success(`${siteId}: ${localeList} / ${currencyList}`);
  }
  return generated;
}

/** Derives countries.generated.ts's shape: URL slug -> {sfccSiteId, locale, currency}. */
function deriveCountriesGenerated(overlay, generated) {
  const countriesGenerated = {};
  for (const pwaSite of overlay) {
    const sourceId = pwaSite.sfccSiteId ?? pwaSite.id;
    const source = generated[sourceId];
    if (!source) continue;
    for (const loc of pwaSite.locales) {
      const match = source.supportedLocales.find((l) => l.id === loc.id);
      if (!match) continue;
      const slug = loc.alias ?? (pwaSite.id === ROOT_SITE_ID ? ROOT_SLUG : loc.id);
      countriesGenerated[slug] = { sfccSiteId: sourceId, locale: loc.id, currency: match.preferredCurrency };
    }
  }
  return countriesGenerated;
}

/** Derives contentfulMapping.generated.ts's shape: SUPPORTED_LOCALES + SITE_LOCALES (per PWA site id). */
function deriveContentfulGenerated(overlay, generated) {
  const siteLocales = {};
  const allLocaleIds = new Set();
  for (const pwaSite of overlay) {
    const sourceId = pwaSite.sfccSiteId ?? pwaSite.id;
    const source = generated[sourceId];
    if (!source) continue;
    const localeIds = pwaSite.locales
      .map((loc) => loc.id)
      .filter((id) => source.supportedLocales.some((l) => l.id === id));
    siteLocales[pwaSite.id] = localeIds;
    localeIds.forEach((id) => allLocaleIds.add(id));
  }
  return { supportedLocales: [...allLocaleIds], siteLocales };
}

/** Derives e2e/fixtures/site.generated.js's shape: fixture key -> {locale, currency, currencySymbol, siteId}. */
function deriveE2eSiteGenerated(overlay, generated) {
  if (!existsSync(E2E_OVERLAY_FILE)) {
    log.warn('e2e/fixtures/site.overlay.js not found — skipping e2e fixture generation.');
    return {};
  }
  const e2eOverlay = require(E2E_OVERLAY_FILE);
  const e2eGenerated = {};
  for (const [fixtureKey, { siteId: pwaSiteId }] of Object.entries(e2eOverlay)) {
    const pwaSite = overlay.find((s) => s.id === pwaSiteId);
    if (!pwaSite) {
      log.warn(`e2e/fixtures/site.overlay.js references unknown PWA site '${pwaSiteId}' for key '${fixtureKey}'.`);
      continue;
    }
    const sourceId = pwaSite.sfccSiteId ?? pwaSite.id;
    const source = generated[sourceId];
    const loc = pwaSite.locales[0];
    const match = source?.supportedLocales.find((l) => l.id === loc.id);
    if (!match) continue;
    e2eGenerated[fixtureKey] = {
      locale: loc.id,
      currency: match.preferredCurrency,
      currencySymbol: currencySymbolFor(match.preferredCurrency),
      siteId: pwaSiteId,
    };
  }
  return e2eGenerated;
}

function renderContent(target, data) {
  const timestamp = new Date().toISOString();
  const doNotEdit = `AUTO-GENERATED by \`npm run sync:regional-config\` — do not edit by hand.`;

  if (target.format === 'cjs') {
    return `/*
 * ${doNotEdit}
 * Source of truth: live SFCC site configuration via SCAPI Shopper
 * Configurations, merged with the hand-maintained overlay in
 * ${target.consumer}.
 * Last synced: ${timestamp}
 */
module.exports = ${JSON.stringify(data, null, 2)};
`;
  }
  if (target.format === 'ts') {
    return `/*
 * ${doNotEdit}
 * Source of truth: live SFCC site configuration via SCAPI Shopper
 * Configurations, merged with the hand-maintained overlay in
 * ${target.consumer}.
 * Last synced: ${timestamp}
 */
export const ${target.exportName} = ${JSON.stringify(data, null, 2)} as const;
`;
  }
  // ts-contentful: two named exports instead of one
  return `/*
 * ${doNotEdit}
 * Source of truth: live SFCC site configuration via SCAPI Shopper
 * Configurations. Consumed by ${target.consumer}, which adds the
 * Contentful-specific constants this data doesn't cover.
 * Last synced: ${timestamp}
 */
export const SUPPORTED_LOCALES = ${JSON.stringify(data.supportedLocales, null, 2)} as const;
export const SITE_LOCALES: Record<string, readonly string[]> = ${JSON.stringify(data.siteLocales, null, 2)};
`;
}

async function main() {
  if (!existsSync(SITES_OVERLAY_FILE)) {
    log.error(`config/sites.overlay.js not found. It must exist before syncing.`);
    process.exit(1);
  }
  const overlay = require(SITES_OVERLAY_FILE);

  log.section('Fetching live site configuration from SCAPI (Shopper Configurations)');
  const generated = await fetchGeneratedSites(overlay);

  log.section('Deriving countries / contentful / e2e-fixture data from the same fetch');
  const countriesGenerated = deriveCountriesGenerated(overlay, generated);
  const contentfulGenerated = deriveContentfulGenerated(overlay, generated);
  const e2eSiteGenerated = deriveE2eSiteGenerated(overlay, generated);
  log.success(
    `Derived ${Object.keys(countriesGenerated).length} country slugs, ` +
      `${contentfulGenerated.supportedLocales.length} Contentful locales across ` +
      `${Object.keys(contentfulGenerated.siteLocales).length} sites, ` +
      `${Object.keys(e2eSiteGenerated).length} e2e fixture keys.`,
  );

  const outputs = [
    { target: TARGETS.sites, data: generated },
    { target: TARGETS.countries, data: countriesGenerated },
    { target: TARGETS.contentful, data: contentfulGenerated },
    { target: TARGETS.e2eSite, data: e2eSiteGenerated },
  ];

  if (DRY_RUN) {
    log.section('Dry run — would write');
    for (const { target, data } of outputs) {
      console.log(`\n--- ${target.file} ---`);
      console.log(JSON.stringify(data, null, 2));
    }
    return;
  }

  const { approved, login } = await isTier1Approver();
  if (!approved) {
    log.warn(`Authenticated as '${login}' — not a tier-1-approver. Not writing (read-only).`);
    for (const { target, data } of outputs) {
      log.section(`Would write ${target.file}`);
      console.log(JSON.stringify(data, null, 2));
    }
    return;
  }
  log.info(`Authenticated as '${login}' (tier-1-approver). Write access granted.`);

  log.section('Writing generated files');
  // Render + format all four to temp files first (preserving the real
  // extension, e.g. `.generated.ts` -> `.generated.tmp.ts`, so eslint picks
  // the right parser) and only publish them as one unit once every single
  // one succeeds — a mid-way failure must never leave the four generated
  // files in a mixed, inconsistent state.
  const tempPaths = outputs.map(({ target }) => target.file.replace(/(\.\w+)$/, '.tmp$1'));
  try {
    for (let i = 0; i < outputs.length; i++) {
      const { target, data } = outputs[i];
      const tempPath = tempPaths[i];
      writeFileSync(tempPath, renderContent(target, data), 'utf8');
      execSync(`npx eslint --fix "${tempPath}"`, { stdio: 'pipe' });
    }
    for (let i = 0; i < outputs.length; i++) {
      renameSync(tempPaths[i], outputs[i].target.file);
      log.success(`${outputs[i].target.file} written.`);
    }
  } catch (err) {
    for (const tempPath of tempPaths) {
      if (existsSync(tempPath)) unlinkSync(tempPath);
    }
    throw new Error(`Failed to publish generated files — nothing was changed: ${err.message ?? err}`);
  }
  log.success('All generated files written and formatted.');
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

/**
 * SFCC ↔ Contentful mapping constants.
 *
 * Locale/site mapping (SUPPORTED_LOCALES, SITE_LOCALES) comes from
 * contentfulMapping.generated.ts — regenerate via
 * `npm run sync:regional-config`, which derives it from the same SCAPI
 * fetch that populates config/sites.generated.js. The environment ID is
 * injected per MRT tier via the CONTENTFUL_ENVIRONMENT_ID env var; this
 * file provides the canonical reference for what each tier maps to.
 *
 * Tier topology (DEV → TEST → OMS INT → STAGE → UAT → PRODUCTION):
 *   dev | test | sit | staging | uat | master (via 'production' alias)
 */

import { SITE_LOCALES as GENERATED_SITE_LOCALES, SUPPORTED_LOCALES } from './contentfulMapping.generated';

// ── Locale mapping ────────────────────────────────────────────────────────────

export { SUPPORTED_LOCALES };

export type SupportedLocale = (typeof SUPPORTED_LOCALES)[number];

/** The Contentful default locale — all others fall back to this. */
export const DEFAULT_LOCALE: SupportedLocale = 'en';

/**
 * Maps SFCC site IDs to the locale codes they serve.
 * Matches the l10n.supportedLocales configuration in config/sites.js.
 */
export const SITE_LOCALES = GENERATED_SITE_LOCALES as Record<string, readonly SupportedLocale[]>;

// ── Environment mapping ───────────────────────────────────────────────────────

/**
 * Contentful environment IDs per delivery tier.
 * These are the values set in CONTENTFUL_ENVIRONMENT_ID per MRT target.
 * Production uses the 'production' alias which points to 'master'.
 */
export const CONTENTFUL_ENVIRONMENTS = {
  dev: 'dev',
  test: 'test',
  sit: 'sit',
  staging: 'staging',
  uat: 'uat',
  production: 'master',
} as const;

export type ContentfulEnvironment = keyof typeof CONTENTFUL_ENVIRONMENTS;

// ── Content type IDs ──────────────────────────────────────────────────────────

/** Contentful content type IDs used by the app. */
export const CONTENT_TYPE_IDS = {
  shoppableImage: 'shoppableImage',
} as const;

export type ContentTypeId = (typeof CONTENT_TYPE_IDS)[keyof typeof CONTENT_TYPE_IDS];

// ── SFCC product ID field ─────────────────────────────────────────────────────

/**
 * The JSON key used for SFCC master product IDs within Contentful hotspot objects.
 * Matches the shape expected by overrides/app/components/contentful/experiences/shoppableImage.
 */
export const SFCC_PRODUCT_ID_FIELD = 'productId' as const;

