/**
 * Shared utilities for SFCC regional-config sync scripts.
 * Provides SLAS token acquisition, Shopper Configurations (SCAPI) fetch
 * helpers, and the same Tier-1-approver gh-identity check used by
 * scripts/contentful/setup/getConfig.mjs.
 */

import { execSync } from 'child_process';

/** Bounded timeout for both SCAPI requests below — a stalled connection to
 * either endpoint must not hang `npm run sync:regional-config` indefinitely. */
const REQUEST_TIMEOUT_MS = 20_000;

export const log = {
  info: (msg) => console.log(`  ℹ️  ${msg}`),
  success: (msg) => console.log(`  ✅  ${msg}`),
  skip: (msg) => console.log(`  ⏭️   ${msg}`),
  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
  error: (msg) => console.error(`  ❌  ${msg}`),
  section: (msg) => console.log(`\n── ${msg} ──`),
};

/**
 * Validates that the required environment variables are set and non-empty.
 * Exits the process with a descriptive message if any are missing.
 * @param {string[]} required
 */
export function checkEnv(required) {
  const missing = required.filter((k) => !process.env[k]);
  if (missing.length) {
    log.error(`Missing env vars: ${missing.join(', ')}`);
    console.error('   Add them to .env (at repo root) and re-run.\n');
    process.exit(1);
  }
}

/**
 * Checks whether the authenticated gh identity is a member of
 * @ZimmermannAU/tier-1-approvers. Same pattern as
 * scripts/contentful/setup/getConfig.mjs — a fast-fail convenience only;
 * the real enforcement is GitHub branch protection + CODEOWNERS.
 * @returns {Promise<{approved: boolean, login: string}>}
 */
export async function isTier1Approver() {
  try {
    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
      encoding: 'utf8',
    }).trim();
    const members = membersRaw.split('\n').filter(Boolean);
    return { approved: members.includes(login), login };
  } catch {
    return { approved: false, login: 'unknown' };
  }
}

/**
 * Fetches a SLAS guest shopper access token using the private-client
 * client_credentials grant (server-to-server, no shopper login) — the same
 * credentials (COMMERCE_API_CLIENT_ID + PWA_KIT_SLAS_CLIENT_SECRET) the
 * running storefront already uses. Guest tokens are scoped to a single
 * site via `channel_id` (SLAS's name for the SFCC site ID) — SLAS rejects
 * a guest token request with no channel_id, so a fresh token is needed per
 * site rather than one shared token.
 * @param {string} siteId the SFCC site ID to scope the token to
 * @returns {Promise<string>} access token
 */
export async function getSlasToken(siteId) {
  const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID, COMMERCE_API_CLIENT_ID, PWA_KIT_SLAS_CLIENT_SECRET } =
    process.env;
  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/shopper/auth/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/oauth2/token`;
  const basicAuth = Buffer.from(`${COMMERCE_API_CLIENT_ID}:${PWA_KIT_SLAS_CLIENT_SECRET}`).toString('base64');

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${basicAuth}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: siteId }).toString(),
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw new Error(`SLAS token request failed for site '${siteId}': ${response.status} ${await response.text()}`);
  }
  const { access_token: accessToken } = await response.json();
  return accessToken;
}

/**
 * Fetches live site configuration (name, status, currencies, locales) for a
 * single SFCC site from the Shopper Configurations API — the current,
 * non-deprecated SCAPI successor to OCAPI's Data API site-preferences read.
 * One call per site; there is no org-wide "list all sites" call.
 * @param {string} accessToken SLAS shopper access token
 * @param {string} siteId real SFCC site ID
 * @returns {Promise<object>} the raw configurations response
 */
export async function fetchSiteConfiguration(accessToken, siteId) {
  const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID } = process.env;
  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/configuration/shopper-configurations/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/configurations?siteId=${encodeURIComponent(
    siteId,
  )}`;

  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw new Error(
      `Shopper Configurations request failed for site '${siteId}': ${response.status} ${await response.text()}`,
    );
  }
  return response.json();
}

