// READ-ONLY V&V probe: does ZimmermannUSIntl exist in SCAPI, and with en-CA?
// Uses the repo's own read-only SCAPI helpers. No writes anywhere.
import { pathToFileURL } from 'url';

const shared = await import(
  pathToFileURL('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/sfcc/_shared.mjs').href
);
const { getSlasToken, fetchSiteConfiguration } = shared;

function summarize(raw) {
  const fields = Object.fromEntries(
    (raw?.configurations ?? [])
      .filter((c) => c.configurationType === 'siteConfiguration')
      .map((c) => [c.id, c.value]),
  );
  const locales = Array.isArray(fields.allowedLocales)
    ? fields.allowedLocales.filter((l) => l.id !== 'default').map((l) => l.id)
    : fields.allowedLocales;
  return {
    status: fields.status,
    defaultLocale: fields.defaultLocale,
    allowedLocales: locales,
    allowedCurrencies: fields.allowedCurrencies,
  };
}

// Control site (known-good) first, then the target.
for (const site of ['ZimmermannUS', 'ZimmermannUSIntl']) {
  try {
    const token = await getSlasToken(site);
    const raw = await fetchSiteConfiguration(token, site);
    console.log(`${site} => ${JSON.stringify(summarize(raw))}`);
  } catch (e) {
    console.log(`${site} ERROR: ${e.message}`);
  }
}

