// READ-ONLY: compare DEV live SCAPI config for every real SFCC site against
// the committed config/sites.generated.js, to prove a sync-from-DEV would
// change ONLY US-INTL and not silently drift the other 7 sites.
import { pathToFileURL } from 'url';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const REPO = '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa';
const shared = await import(pathToFileURL(`${REPO}/scripts/sfcc/_shared.mjs`).href);
const { getSlasToken, fetchSiteConfiguration } = shared;
const committed = require(`${REPO}/config/sites.generated.js`);

function live(raw) {
  const f = Object.fromEntries(
    (raw?.configurations ?? [])
      .filter((c) => c.configurationType === 'siteConfiguration')
      .map((c) => [c.id, c.value]),
  );
  return {
    defaultCurrency: f.defaultCurrency,
    currencies: f.allowedCurrencies,
    locales: (f.allowedLocales ?? []).filter((l) => l.id !== 'default').map((l) => l.id),
  };
}

const realSites = [
  'ZimmermannAU', 'ZimmermannUS', 'ZimmermannUK', 'ZimmermannEU',
  'ZimmermannEUIntl', 'ZimmermannHK', 'ZimmermannME', 'ZimmermannUSIntl',
];

const sortJoin = (a) => [...a].sort().join(',');

for (const site of realSites) {
  try {
    const token = await getSlasToken(site);
    const L = live(await fetchSiteConfiguration(token, site));
    const C = committed[site];
    const cLoc = C ? C.supportedLocales.map((l) => l.id) : null;
    const cCcy = C ? C.supportedCurrencies : null;
    const localeMatch = C ? sortJoin(cLoc) === sortJoin(L.locales) : 'NEW(not in committed)';
    const ccyMatch = C ? sortJoin(cCcy) === sortJoin(L.currencies) : 'NEW';
    console.log(
      `${site}\n  DEV       locales=[${L.locales}] ccy=[${L.currencies}]\n  committed locales=[${cLoc ?? '—'}] ccy=[${cCcy ?? '—'}]\n  => localeMatch=${localeMatch} ccyMatch=${ccyMatch}`,
    );
  } catch (e) {
    console.log(`${site} ERROR: ${e.message}`);
  }
}

