// READ-ONLY: is en-CA enabled on ZimmermannUSIntl for the instance this env points at?
// Classifies failures so "not enabled" is never confused with "instance down / no creds".
import { pathToFileURL } from 'url';

const shared = await import(
  pathToFileURL('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/sfcc/_shared.mjs').href
);
const { getSlasToken, fetchSiteConfiguration } = shared;

const SITE = 'ZimmermannUSIntl';
const org = process.env.COMMERCE_API_ORGANIZATION_ID || '(no org set)';

try {
  const token = await getSlasToken(SITE);
  const raw = await fetchSiteConfiguration(token, SITE);
  const fields = Object.fromEntries(
    (raw?.configurations ?? [])
      .filter((c) => c.configurationType === 'siteConfiguration')
      .map((c) => [c.id, c.value]),
  );
  const locales = Array.isArray(fields.allowedLocales)
    ? fields.allowedLocales.filter((l) => l.id !== 'default').map((l) => l.id)
    : fields.allowedLocales;
  const hasEnCa = Array.isArray(locales) && locales.includes('en-CA');
  console.log(`org=${org}  status=${fields.status}  locales=[${locales}]  => en-CA ${hasEnCa ? 'ENABLED ✅' : 'NOT enabled ❌'}`);
} catch (e) {
  const m = e.message || String(e);
  let kind;
  if (/Site Not Found|No site with ID|site-not-found/i.test(m)) kind = 'SITE DOES NOT EXIST on this tier ⛔';
  else if (/\b52\d\b/.test(m)) kind = 'INSTANCE UNREACHABLE (5xx) — cannot determine right now ⏳';
  else if (/SLAS token request failed/i.test(m)) kind = 'CANNOT CHECK (SLAS/creds/org not available locally) ❔';
  else kind = `ERROR: ${m.slice(0, 120)}`;
  console.log(`org=${org}  => ${kind}`);
}

