    console.error(`${sourceLabel} doesn't exist yet — run \`npm run env -- init\` first.`);
    process.exit(1);
  }

  const { approved, login } = isTier1Approver();
  if (!approved) {
    console.log(
      `Authenticated as '${login}' — not a tier-1-approver. Only tier-1-approvers can push to GitHub Environments.`,
    );
    return;
  }

  // Personal-scope keys (present in .env.shared, merged in for tier pushes
  // too) never leave this machine — pushing your own Jira/CMA token would
  // put every teammate's actions under your identity.
  const entries = allEntries.filter(([key]) => !PERSONAL_KEYS.has(key));
  const skippedPersonal = allEntries.length - entries.length;
  if (skippedPersonal) {
    console.log(
      `Excluding ${skippedPersonal} personal-scope value(s) — these are never pushed: ${allEntries
        .filter(([key]) => PERSONAL_KEYS.has(key))
        .map(([key]) => key)
        .join(', ')}`,
    );
  }
  if (!entries.length) {
    console.log(`Nothing to push — ${sourceLabel} has no filled-in, push-eligible values yet.`);
    return;
  }

  const tempFile = path.join(os.tmpdir(), `.env.push-${scope}.tmp`);
  fs.writeFileSync(tempFile, entries.map(([key, value]) => `${key}=${value}`).join('\n') + '\n');
  try {
    execSync(`gh variable set -f "${tempFile}" --env ${scope}`, { stdio: 'inherit' });
    console.log(`Pushed ${entries.length} value(s) to the "${scope}" GitHub Environment.`);
  } finally {
    fs.unlinkSync(tempFile);
  }
}

// ── Contentful auto-fetch (init) ────────────────────────────────────────────
// Same tier-1-approver gate as scripts/contentful/setup/getConfig.mjs — kept as
// a small local copy rather than importing it, since it isn't exported there.
function isTier1Approver() {
  try {
    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    const membersRaw = execSync("gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'", {
      encoding: 'utf8',
    }).trim();
    const members = membersRaw.split('\n').filter(Boolean);
    return { approved: members.includes(login), login };
  } catch {
    return { approved: false, login: 'unknown' };
  }
}

// contentful-management errors stringify their `.message` as the full raw API
// error body (headers, request id, everything) — pull out just the human part.
function contentfulErrorMessage(err) {
  try {
    const parsed = JSON.parse(err.message);
    if (parsed?.message) return parsed.message;
  } catch {
    // not JSON — fall through to the raw message
  }
  return err.message;
}

async function fetchContentfulTokenMap(managementToken, spaceId) {
  process.env.CONTENTFUL_MANAGEMENT_TOKEN = managementToken;
  process.env.CONTENTFUL_SPACE_ID = spaceId;
  const client = createContentfulClient();

  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
  const tokenMap = {};
  for (const key of apiKeys) {
    const envLink = key.environments?.[0];
    if (!envLink) continue;
    const envId = envLink.sys.id;
    let previewToken = '';
    if (key.preview_api_key?.sys?.id) {
      try {
        const previewKey = await client.previewApiKey.get({ previewApiKeyId: key.preview_api_key.sys.id });
        previewToken = previewKey.accessToken;
      } catch {
        // non-fatal — preview key may not exist yet
      }
    }
    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
  }
  return tokenMap;
}

