// READ-ONLY diagnostic for the shopper-context 412 (test) vs 404 (dev) mystery.
// Reuses the repo's own read-only SLAS/SCAPI helpers. GET only — no writes.
import { pathToFileURL } from 'url';
import { randomUUID } from 'crypto';

const shared = await import(
  pathToFileURL('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/sfcc/_shared.mjs').href
);
const { getSlasToken } = shared;

const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID } = process.env;

async function checkShopperContext(siteId, usid) {
  const token = await getSlasToken(siteId);
  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/shopper/shopper-context/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/shopper-context/${usid}?siteId=${encodeURIComponent(siteId)}`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  const bodyText = await res.text();
  return { status: res.status, bodyText };
}

const org = COMMERCE_API_ORGANIZATION_ID;
console.log(`\n=== org=${org} ===`);

// Test 1: multiple fresh random usids on ZimmermannUS — is it usid-specific?
console.log('\n-- ZimmermannUS, 3 fresh random usids --');
for (let i = 0; i < 3; i++) {
  const usid = randomUUID();
  try {
    const { status, bodyText } = await checkShopperContext('ZimmermannUS', usid);
    console.log(`  usid=${usid} -> ${status}  body=${bodyText}`);
  } catch (e) {
    console.log(`  usid=${usid} -> ERROR ${e.message}`);
  }
}

// Test 2: other real sites on the SAME org — is it site-specific or org-wide?
console.log('\n-- other sites on this org, 1 fresh usid each --');
for (const site of ['ZimmermannAU', 'ZimmermannUK', 'ZimmermannUS', 'ZimmermannHK']) {
  const usid = randomUUID();
  try {
    const { status, bodyText } = await checkShopperContext(site, usid);
    console.log(`  ${site} usid=${usid} -> ${status}  body=${bodyText}`);
  } catch (e) {
    console.log(`  ${site} -> ERROR ${e.message}`);
  }
}

