// READ-ONLY: check via the Shopper Configurations endpoint (not shopper-context)
// whether staging's real sites exist at all, to corroborate/refute the
// "Site Not Found" seen via shopper-context.
import { pathToFileURL } from 'url';
const shared = await import(
  pathToFileURL('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/sfcc/_shared.mjs').href
);
const { getSlasToken, fetchSiteConfiguration } = shared;

for (const site of ['ZimmermannAU', 'ZimmermannUS', 'ZimmermannUK', 'ZimmermannEU', 'ZimmermannEUIntl', 'ZimmermannHK', 'ZimmermannME']) {
  try {
    const token = await getSlasToken(site);
    const raw = await fetchSiteConfiguration(token, site);
    const status = (raw?.configurations ?? []).find((c) => c.id === 'status')?.value;
    console.log(`${site} -> OK, status=${status}`);
  } catch (e) {
    console.log(`${site} -> ERROR: ${e.message.slice(0, 150)}`);
  }
}

